        char_occurrences = [[0] * word_length for _ in range(self.ALPHABET_SIZE)]
        for col in range(word_length):
            for word in words:
                char_occurrences[ord(word[col]) - ord('a')][col] += 1
        dp = [[-1] * (word_length + 1) for _ in range(target_length + 1)]

